    summary = "Walk the happy path first. Understand what a system wants to do well before poking at its edges."
    content = "When you arrive somewhere new, resist the urge to immediately test the edges. Walk the happy path first. Understand what the system wants to do well before you explore what it does under stress. You learn more about a community by participating in it than by poking at it. This applies to APIs, teams, and neighborhoods alike."
    artifactType = "insight"
    tags = "community,onboarding,philosophy"
} | ConvertTo-Json

